select * from breeding_cycles
where  and id = #{id}
limit 1

select * from breeding_cycles
where  and id = #{id}
limit 1 for update

select * from breeding_cycles
where house_id = #{houseId} and batch_id = #{batchId}

    and mother_rabbit_id = #{motherRabbitId}


    and closed_at is null

order by mother_rabbit_id, cycle_no desc

select * from breeding_cycles where and status in
#{status}
order by cycle_no desc, id desc limit 1 for update

select * from breeding_cycles where and status in
#{status}
order by cycle_no asc, id asc limit 1 for update

mapper.update:
update breeding_cycles
set overlap_end_date = #{overlapEndDate},
    overlap_days = greatest(0, timestampdiff(day, overlap_start_date, #{overlapEndDate})),
    update_by = #{updateBy},
    update_time = now()
where house_id = #{houseId}
  and batch_id = #{batchId}
  and mother_rabbit_id = #{motherRabbitId}
  and overlap_litter_cycle_no = #{litterCycleNo}
  and overlap_start_date is not null
  and overlap_end_date is null

