from breeding_cycles
where house_id = #{houseId}
  and batch_id = #{batchId}
  and closed_at is null

select count(1)
from breeding_cycles
where house_id = #{houseId}
  and batch_id = #{batchId}
  and mother_rabbit_id = #{motherRabbitId}
  and closed_at is null

select * from breeding_cycles where house_id = #{houseId} and closed_at is null and next_event_date is not null and next_event_date <= #{today}
and is_event_notified = false
order by next_event_date, id
